package org.apache.commons.cli;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.*;

public class OptionBuilderTest {

    private static String getDescription() throws Exception {
        Field f = OptionBuilder.class.getDeclaredField("description");
        f.setAccessible(true);
        return (String) f.get(null);
    }

    private static OptionBuilder getInstanceField() throws Exception {
        Field f = OptionBuilder.class.getDeclaredField("INSTANCE");
        f.setAccessible(true);
        return (OptionBuilder) f.get(null);
    }

    private static void setDescription(String value) throws Exception {
        Field f = OptionBuilder.class.getDeclaredField("description");
        f.setAccessible(true);
        f.set(null, value);
    }

    @AfterEach
    public void tearDown() throws Exception {
        // reset description to initial state (null)
        setDescription(null);
    }

    @Test
    public void testWithDescriptionSetsDescriptionAndReturnsInstance() throws Exception {
        OptionBuilder returned = OptionBuilder.withDescription("my-desc");

        OptionBuilder instance = getInstanceField();
        assertSame(instance, returned, "withDescription should return the singleton INSTANCE");

        assertEquals("my-desc", getDescription(), "description field should be set to provided value");
    }

    @Test
    public void testWithDescriptionNullSetsNull() throws Exception {
        // set an initial non-null value to ensure null overwrites it
        setDescription("initial");
        OptionBuilder returned = OptionBuilder.withDescription(null);

        OptionBuilder instance = getInstanceField();
        assertSame(instance, returned, "withDescription should return the singleton INSTANCE even when null passed");

        assertNull(getDescription(), "description field should be set to null when null passed");
    }

    @Test
    public void testWithDescriptionEmptyString() throws Exception {
        OptionBuilder returned = OptionBuilder.withDescription("");
        OptionBuilder instance = getInstanceField();
        assertSame(instance, returned, "withDescription should return INSTANCE for empty string");

        assertEquals("", getDescription(), "description should be set to empty string");
    }

    @Test
    public void testMultipleCallsOverwriteDescription() throws Exception {
        OptionBuilder.withDescription("first");
        assertEquals("first", getDescription(), "after first call description should be 'first'");

        OptionBuilder.withDescription("second");
        assertEquals("second", getDescription(), "after second call description should be 'second'");

        // final check instance identity still consistent
        OptionBuilder instance = getInstanceField();
        OptionBuilder returned = OptionBuilder.withDescription("third");
        assertSame(instance, returned, "returned INSTANCE should remain the same across multiple calls");
        assertEquals("third", getDescription(), "description should follow the last call");
    }
}

